import sys, unittest
from pathlib import Path
ROOT = Path(__file__).parent
sys.path[:0] = [str(ROOT/'api'), str(ROOT/'admin')]
from approvals import approve_batch
from view import show_approvals
class PanelTest(unittest.TestCase):
    def test_existing_menu_access(self):
        for permission in ['catalog:manage', 'orders:manage']:
            with self.subTest(permission=permission):
                self.assertTrue(show_approvals({'permissions':[permission]}))
        self.assertFalse(show_approvals({'permissions':[]}))
        self.assertFalse(show_approvals({'permissions':['inventory:read', 'pricing:read']}))
    def test_inventory_and_pricing_menu_access(self):
        for permission in ['inventory:manage', 'pricing:manage']:
            with self.subTest(permission=permission):
                self.assertTrue(show_approvals({'permissions':[permission]}))
    def test_api_boundaries(self):
        user={'business_id':'a','permissions':['inventory:manage']}
        p={'id':'p','business_id':'a','area':'inventory','grant_key':'g'}
        self.assertEqual(approve_batch(user,[p],'g')[0]['status'],'approved')
        for u,k in [(dict(user,business_id='b'),'g'),(dict(user,permissions=[]),'g'),(user,'bad')]:
            with self.assertRaises(PermissionError): approve_batch(u,[p],k)
    def test_visible_panel_preserves_area_authorization(self):
        for area, other in [('inventory', 'pricing'), ('pricing', 'inventory')]:
            with self.subTest(area=area):
                user={'business_id':'a','permissions':[area + ':manage']}
                proposal={'id':'p','business_id':'a','area':area,'grant_key':'g'}
                self.assertTrue(show_approvals(user))
                self.assertEqual(approve_batch(user,[proposal],'g')[0]['status'],'approved')
                for changed, key in [(dict(proposal,area=other),'g'),
                                     (dict(proposal,business_id='b'),'g'),
                                     (proposal,'bad')]:
                    with self.assertRaises(PermissionError):
                        approve_batch(user,[changed],key)
                with self.assertRaises(PermissionError):
                    approve_batch(user,[proposal,dict(proposal,id='q',area=other)],'g')

